// Supabase Edge Function — sends a copy of a signed consent (currently: Laser
// αποτρίχωσης) to the patient, FROM yourbeautyline@gmail.com. Sends via the
// Gmail API (same mechanism as send-consultation-email/send-report-email) —
// Required secrets: GOOGLE_CLIENT_ID, GOOGLE_CLIENT_SECRET, BL_REFRESH_TOKEN
// (all shared with those other two functions).
//
// The full legal consent document is attached as a real PDF (not HTML) —
// built entirely server-side with pdf-lib + an embedded Greek-subset font
// (Noto Sans, SIL Open Font License, embedded as base64 below so this
// function has zero runtime network dependency for the font). The signature
// PNG the patient drew on-screen is decoded from its data URL and embedded
// as an image in the PDF.
//
// Called from index.html via:
//   sb.functions.invoke('send-consent-email', {
//     body: { to, subject, html, consent_pdf: {
//       type: 'laser', clinic_name, patient_name, signed_at, collected_by,
//       photo_consent, signature_data_url,
//     }, attachment_name }
//   })
//
// Deploy with:
//   supabase functions deploy send-consent-email

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import { PDFDocument, rgb } from 'https://esm.sh/pdf-lib@1.17.1';
import fontkit from 'https://esm.sh/@pdf-lib/fontkit@1.1.1';

const cors = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

function json(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...cors, 'Content-Type': 'application/json' },
  });
}

async function getAccessToken(): Promise<string> {
  const res = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      client_id: Deno.env.get('GOOGLE_CLIENT_ID')!,
      client_secret: Deno.env.get('GOOGLE_CLIENT_SECRET')!,
      refresh_token: Deno.env.get('BL_REFRESH_TOKEN')!,
      grant_type: 'refresh_token',
    }),
  });
  const data = await res.json();
  if (!data.access_token) throw new Error('Token error: ' + JSON.stringify(data));
  return data.access_token;
}

// Byte array -> base64 (works for both UTF-8 text bytes and raw binary, e.g. PDF bytes)
function bytesToBase64(bytes: Uint8Array): string {
  let bin = '';
  bytes.forEach((b) => { bin += String.fromCharCode(b); });
  return btoa(bin);
}
function b64utf8(s: string): string {
  return bytesToBase64(new TextEncoder().encode(s));
}
function base64ToBytes(b64: string): Uint8Array {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}
// data:image/png;base64,.... -> raw PNG bytes
function dataUrlToBytes(dataUrl: string): Uint8Array {
  const comma = dataUrl.indexOf(',');
  return base64ToBytes(comma >= 0 ? dataUrl.slice(comma + 1) : dataUrl);
}

// ── Greek-subset Noto Sans (SIL OFL 1.1) embedded as base64 — Regular + Bold ──
// Subsetted to Basic Latin + Latin-1 Supplement + Greek & Coptic + general
// punctuation (en/em dash, bullet, smart quotes) + Euro sign — everything the
// laser consent text below actually uses. Regenerate by instancing
// https://github.com/google/fonts NotoSans[wdth,wght].ttf at the desired
// weight and running fonttools pyftsubset with those unicode ranges.
const NOTO_SANS_REGULAR_B64 = '';
const NOTO_SANS_BOLD_B64 = '';

type Run = { text: string; bold?: boolean };
type Block =
  | { type: 'header'; text: string }
  | { type: 'para'; runs: Run[] }
  | { type: 'spacer'; h: number };

// Ίδιο ακριβώς νομικό κείμενο με το laserConsentText() του index.html — μία
// πηγή αλήθειας θα ήταν καλύτερη μακροπρόθεσμα, αλλά μέχρι τότε αν αλλάξει
// εκεί, ενημέρωσε και εδώ.
function laserConsentBlocks(patientName: string, photoConsent: boolean): Block[] {
  return [
    { type: 'header', text: 'Α. ΕΝΗΜΕΡΩΣΗ ΑΣΘΕΝΟΥΣ — ΑΠΟΤΡΙΧΩΣΗ ΜΕ LASER ALEXANDRITE' },
    { type: 'para', runs: [{ text: 'Η αποτρίχωση με laser Alexandrite είναι μέθοδος προοδευτικής μείωσης της τριχοφυΐας μέσω εκπομπής φωτεινής ενέργειας που απορροφάται από τη μελανίνη του τριχικού θυλάκου. Απαιτούνται επαναλαμβανόμενες συνεδρίες· το αποτέλεσμα διαφέρει ανά φωτότυπο, χρώμα τρίχας και ορμονικούς παράγοντες και δεν είναι εγγυημένη η οριστική αποτρίχωση.' }] },
    { type: 'spacer', h: 6 },
    { type: 'para', runs: [{ text: 'Αναμενόμενες παροδικές αντιδράσεις: ', bold: true }, { text: 'ερυθρότητα, οίδημα, αίσθημα καύσου λίγων ωρών.' }] },
    { type: 'para', runs: [{ text: 'Σπάνιες ανεπιθύμητες ενέργειες: ', bold: true }, { text: 'έγκαυμα, φλύκταινες, υπέρ/υπομελάγχρωση, ουλή (σπανίως), παράδοξη υπερτρίχωση.' }] },
    { type: 'spacer', h: 6 },
    { type: 'para', runs: [{ text: 'Αντενδείξεις που δηλώνω ότι δεν συντρέχουν / έχω ενημερώσει σχετικά: ', bold: true }, { text: 'εγκυμοσύνη, ενεργή δερματική λοίμωξη στην περιοχή, πρόσφατη έντονη έκθεση στον ήλιο ή αυτομαυρίσματος, λήψη φωτοευαισθητοποιών φαρμάκων (π.χ. ισοτρετινοΐνη), ιστορικό χηλοειδών.' }] },
    { type: 'spacer', h: 6 },
    { type: 'para', runs: [{ text: 'Μεσοδιάστημα συνεδριών: ', bold: true }, { text: 'Για αποτελεσματική θεραπεία, οι συνεδρίες πρέπει να επαναλαμβάνονται σε μεσοδιάστημα ' }, { text: '30–40 ημερών', bold: true }, { text: ', με καθοδήγηση της ειδικής εφαρμόστριας. Μεγαλύτερο διάστημα από αυτό μπορεί να οδηγήσει σε μειωμένα αποτελέσματα της θεραπείας.' }] },
    { type: 'spacer', h: 6 },
    { type: 'para', runs: [{ text: 'Οδηγίες: ', bold: true }, { text: 'αποφυγή έκθεσης στον ήλιο για ' }, { text: '6–8 ημέρες', bold: true }, { text: ' πριν και μετά τη συνεδρία, χρήση ' }, { text: 'εξειδικευμένου αντηλιακού', bold: true }, { text: ' υψηλής προστασίας σύμφωνα με τις οδηγίες της εφαρμόστριας.' }] },
    { type: 'spacer', h: 10 },
    { type: 'header', text: 'Β. ΔΗΛΩΣΗ ΣΥΝΑΙΝΕΣΗΣ' },
    { type: 'para', runs: [
      { text: 'Ο/Η υπογράφων/ουσα ' },
      { text: patientName, bold: true },
      { text: ' δηλώνω ότι ενημερώθηκα πλήρως και κατανοητά για τη φύση, τα οφέλη, τους κινδύνους και τις εναλλακτικές της θεραπείας, είχα τη δυνατότητα να υποβάλω ερωτήσεις και έλαβα απαντήσεις. ' },
      { text: 'Συναινώ ελεύθερα στη διενέργεια αποτρίχωσης με laser Alexandrite. Η παρούσα συναίνεση καλύπτει το σύνολο των μελλοντικών συνεδριών laser αποτρίχωσης, συμπεριλαμβανομένης της προσθήκης νέων περιοχών σώματος, και παραμένει σε ισχύ έως έγγραφης ανάκλησής της.', bold: true },
    ] },
    { type: 'spacer', h: 10 },
    { type: 'header', text: 'Γ. ΦΩΤΟΓΡΑΦΙΕΣ' },
    { type: 'para', runs: [{ text: (photoConsent ? '[X] ' : '[ ] ') + 'Συναινώ στη λήψη φωτογραφιών των περιοχών θεραπείας αποκλειστικά για τον ιατρικό μου φάκελο και την παρακολούθηση της πορείας της θεραπείας.' }] },
  ];
}

async function buildLaserConsentPdf(opts: {
  clinicName: string;
  patientName: string;
  signedAtIso: string;
  collectedBy: string;
  photoConsent: boolean;
  signaturePngBytes?: Uint8Array;
}): Promise<Uint8Array> {
  const doc = await PDFDocument.create();
  doc.registerFontkit(fontkit);
  const font = await doc.embedFont(base64ToBytes(NOTO_SANS_REGULAR_B64), { subset: true });
  const fontBold = await doc.embedFont(base64ToBytes(NOTO_SANS_BOLD_B64), { subset: true });

  const pageWidth = 595.28, pageHeight = 841.89; // A4 σε points
  const marginX = 50, marginTop = 56, marginBottom = 50;
  const maxWidth = pageWidth - marginX * 2;

  let page = doc.addPage([pageWidth, pageHeight]);
  let y = pageHeight - marginTop;

  const navy = rgb(0.055, 0.153, 0.341);
  const darkText = rgb(0.094, 0.110, 0.118);
  const grayText = rgb(0.267, 0.275, 0.310);

  const ensureSpace = (h: number) => {
    if (y - h < marginBottom) {
      page = doc.addPage([pageWidth, pageHeight]);
      y = pageHeight - marginTop;
    }
  };

  function wrapRuns(runs: Run[], size: number) {
    const words: { text: string; bold: boolean }[] = [];
    for (const r of runs) {
      r.text.split(' ').forEach((w) => { if (w) words.push({ text: w, bold: !!r.bold }); });
    }
    const lines: { text: string; bold: boolean }[][] = [];
    let cur: { text: string; bold: boolean }[] = [];
    let curWidth = 0;
    const sw = font.widthOfTextAtSize(' ', size);
    for (const w of words) {
      const f = w.bold ? fontBold : font;
      const ww = f.widthOfTextAtSize(w.text, size);
      const add = (cur.length ? sw : 0) + ww;
      if (curWidth + add > maxWidth && cur.length) {
        lines.push(cur); cur = [w]; curWidth = ww;
      } else {
        cur.push(w); curWidth += add;
      }
    }
    if (cur.length) lines.push(cur);
    return lines;
  }

  function drawLine(line: { text: string; bold: boolean }[], size: number, color: ReturnType<typeof rgb>) {
    let cx = marginX;
    const sw = font.widthOfTextAtSize(' ', size);
    for (const w of line) {
      const f = w.bold ? fontBold : font;
      page.drawText(w.text, { x: cx, y, size, font: f, color });
      cx += f.widthOfTextAtSize(w.text, size) + sw;
    }
  }

  function writeParagraph(runs: Run[], size = 10, lineHeight = 14, color = darkText) {
    const lines = wrapRuns(runs, size);
    for (const line of lines) {
      ensureSpace(lineHeight);
      drawLine(line, size, color);
      y -= lineHeight;
    }
  }

  function writeHeader(text: string, size = 12) {
    ensureSpace(size + 10);
    page.drawText(text, { x: marginX, y, size, font: fontBold, color: navy });
    y -= size + 10;
  }

  function writeLabel(text: string, size = 9, color = grayText) {
    writeParagraph([{ text }], size, size + 4, color);
  }

  function writeSpacer(h: number) { y -= h; }

  async function writeImage(bytes: Uint8Array, maxW: number, maxH: number) {
    const png = await doc.embedPng(bytes);
    const scale = Math.min(maxW / png.width, maxH / png.height, 1);
    const w = png.width * scale, h = png.height * scale;
    ensureSpace(h + 6);
    page.drawImage(png, { x: marginX, y: y - h, width: w, height: h });
    y -= h + 10;
  }

  // Τίτλος (navy band, ίδιο ύφος με τα emails)
  ensureSpace(34);
  page.drawRectangle({ x: 0, y: y - 6, width: pageWidth, height: 34, color: navy });
  page.drawText(`${opts.clinicName} — Συναίνεση Laser Αποτρίχωσης`, { x: marginX, y: y + 4, size: 13, font: fontBold, color: rgb(1, 1, 1) });
  y -= 40;

  for (const b of laserConsentBlocks(opts.patientName, opts.photoConsent)) {
    if (b.type === 'header') writeHeader(b.text);
    else if (b.type === 'para') writeParagraph(b.runs);
    else if (b.type === 'spacer') writeSpacer(b.h);
  }

  writeSpacer(10);
  const signedDate = new Date(opts.signedAtIso);
  writeLabel(`Υπεγράφη: ${signedDate.toLocaleString('el-GR')} · Συλλογή από: ${opts.collectedBy || '—'} · Συναίνεση φωτογραφιών: ${opts.photoConsent ? 'Ναι' : 'Όχι'}`);
  writeSpacer(6);

  if (opts.signaturePngBytes) {
    writeHeader('Υπογραφή ασθενούς:', 10);
    await writeImage(opts.signaturePngBytes, 220, 90);
  }

  writeSpacer(14);
  writeLabel('Powered by medi360', 8);

  return await doc.save();
}

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: cors });
  if (req.method !== 'POST') return json({ error: 'Method not allowed' }, 405);

  try {
    // Ίδιος έλεγχος authorization/role με το send-consultation-email — η αρχική
    // έκδοση αυτής της function δεν είχε ΚΑΝΕΝΑΝ έλεγχο (οποιοσδήποτε με το
    // anon key μπορούσε να στείλει email ως yourbeautyline@gmail.com σε
    // οποιονδήποτε παραλήπτη με όποιο περιεχόμενο ήθελε).
    const authHeader = req.headers.get('Authorization');
    if (!authHeader) return json({ error: 'Missing Authorization header' }, 401);

    const supabase = createClient(
      Deno.env.get('SUPABASE_URL')!,
      Deno.env.get('SUPABASE_ANON_KEY')!,
      { global: { headers: { Authorization: authHeader } } },
    );
    const { data: { user }, error: userErr } = await supabase.auth.getUser();
    if (userErr || !user) return json({ error: 'Not authenticated' }, 401);

    const { data: profile, error: profileErr } = await supabase
      .from('profiles').select('role').eq('id', user.id).single();
    if (profileErr || !profile) return json({ error: 'Profile not found' }, 403);
    if (!['super_admin', 'clinic_admin', 'therapist'].includes(profile.role)) {
      return json({ error: 'Δεν έχεις δικαίωμα αποστολής συναίνεσης' }, 403);
    }

    const { to, subject, html, consent_pdf, attachment_name } = await req.json();
    if (!to || !subject || !html) return json({ error: 'Λείπουν πεδία (to/subject/html)' }, 400);

    const token = await getAccessToken();
    const boundary = 'medi360consent';

    const parts = [
      `From: ${String((consent_pdf && consent_pdf.clinic_name) || 'Beauty Line').replace(/[\r\n]/g, '')} <yourbeautyline@gmail.com>`,
      `To: ${to}`,
      `Subject: =?UTF-8?B?${b64utf8(subject)}?=`,
      `MIME-Version: 1.0`,
      `Content-Type: multipart/mixed; boundary="${boundary}"`,
      ``,
      `--${boundary}`,
      `Content-Type: text/html; charset="UTF-8"`,
      `Content-Transfer-Encoding: base64`,
      ``,
      b64utf8(html),
    ];

    if (consent_pdf && consent_pdf.type === 'laser') {
      const pdfBytes = await buildLaserConsentPdf({
        clinicName: consent_pdf.clinic_name || 'Beauty Line',
        patientName: consent_pdf.patient_name || '',
        signedAtIso: consent_pdf.signed_at || new Date().toISOString(),
        collectedBy: consent_pdf.collected_by || '',
        photoConsent: !!consent_pdf.photo_consent,
        signaturePngBytes: consent_pdf.signature_data_url ? dataUrlToBytes(consent_pdf.signature_data_url) : undefined,
      });
      const fname = attachment_name || 'Synainesi.pdf';
      parts.push(
        `--${boundary}`,
        `Content-Type: application/pdf; name="${fname}"`,
        `Content-Disposition: attachment; filename="${fname}"`,
        `Content-Transfer-Encoding: base64`,
        ``,
        bytesToBase64(pdfBytes),
      );
    }
    parts.push(`--${boundary}--`);

    const raw = b64utf8Join(parts);

    const res = await fetch('https://gmail.googleapis.com/gmail/v1/users/me/messages/send', {
      method: 'POST',
      headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' },
      body: JSON.stringify({ raw }),
    });
    const out = await res.json();
    if (out.error) return json({ error: JSON.stringify(out.error) }, 502);

    return json({ ok: true, id: out.id });
  } catch (e) {
    return json({ error: e instanceof Error ? e.message : String(e) }, 500);
  }
});

// parts.join('\r\n') περιέχει ήδη raw base64 (ASCII) για τα binary/utf8 blocks,
// οπότε είναι ασφαλές να το ξανα-base64-άρουμε ως απλό string (TextEncoder
// σε καθαρά ASCII δεδομένα δεν αλλοιώνει τίποτα).
function b64utf8Join(parts: string[]): string {
  return b64utf8(parts.join('\r\n')).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
